INSERT INTO public.sources_sourceurlpattern (
    id,
    source_id,
    pattern,
    pattern_type,
    match_type,
    priority,
    is_active,
    description,
    created_at,
    updated_at
)
SELECT
    gen_random_uuid(),
    source.id,
    pattern_data.pattern,
    pattern_data.pattern_type,
    CASE
        WHEN pattern_data.is_regex THEN 'regex'
        ELSE 'contains'
    END AS match_type,
    CASE
        WHEN pattern_data.pattern_type = 'deny' THEN 10
        ELSE 100
    END AS priority,
    pattern_data.is_active,
    pattern_data.description,
    NOW(),
    NOW()
FROM pattern_data
JOIN public.sources_source AS source
    ON source.code = pattern_data.source_code
ON CONFLICT (source_id, pattern_type, match_type, pattern)
DO UPDATE SET
    priority = EXCLUDED.priority,
    is_active = EXCLUDED.is_active,
    description = EXCLUDED.description,
    updated_at = NOW();

COMMIT;

